 const loadCore=useCallback(async({force=false}={})=>{
  const request=++coreRequestRef.current;
  setBusy(true);
  setError('');
  const failures=[];
  const teamsTask=api('/api/teams',{cache:!force}).then(result=>{
    if(request!==coreRequestRef.current)return;
    setTeams(Array.isArray(result?.data)?result.data:[]);
    setLastSync(new Date());
  }).catch(error=>{
    if(request===coreRequestRef.current)failures.push('Times: '+(error?.message||'indisponíveis'));
  });
  const gamesTask=api(`/api/games?start=${from}&end=${to}${force?'&refresh=1':''}`,{cache:!force}).then(result=>{
    if(request!==coreRequestRef.current)return;
    const incoming=Array.isArray(result?.data)?result.data:[];
    setGames(current=>{
      const sameGame=(left,right)=>{
        if(!left||!right)return false;
        const leftId=String(left.id??''),rightId=String(right.id??'');
        if(leftId&&rightId&&leftId===rightId)return true;
        return Boolean(left.date&&left.date===right.date&&left.home_team?.abbreviation&&left.home_team.abbreviation===right.home_team.abbreviation&&left.visitor_team?.abbreviation&&left.visitor_team.abbreviation===right.visitor_team.abbreviation);
      };
      const merged=incoming.map(game=>{
        const previous=current.find(item=>sameGame(item,game));
        if(!previous)return game;
        const statusRank={scheduled:0,in_progress:1,final:2};
        const previousRank=statusRank[previous.status_state]??0;
        const incomingRank=statusRank[game.status_state]??0;
        // A resposta nova vence quando está no mesmo estágio ou avança o jogo.
        // Só preservamos o estado ao vivo anterior se a API de calendário vier atrasada.
        if(previousRank>incomingRank){
          return {
            ...previous,...game,
            status:previous.status,
            status_state:previous.status_state,
            period:previous.period??game.period??null,
            period_label:previous.period_label||game.period_label||'',
            display_clock:previous.status_state==='final'?null:(previous.display_clock??game.display_clock??null),
            home_team_score:previous.home_team_score??game.home_team_score??null,
            visitor_team_score:previous.visitor_team_score??game.visitor_team_score??null
          };
        }
        return {
          ...previous,...game,
          home_team_score:game.home_team_score??previous.home_team_score??null,
          visitor_team_score:game.visitor_team_score??previous.visitor_team_score??null,
          display_clock:game.status_state==='final'?null:(game.display_clock??previous.display_clock??null)
        };
      });
      current.filter(item=>['in_progress','final'].includes(item.status_state)&&!merged.some(game=>sameGame(item,game))).forEach(item=>merged.push(item));
      return merged.sort((x,y)=>new Date(x.datetime||x.date)-new Date(y.datetime||y.date));
    });
    setGamesLoaded(true);
    setLastSync(new Date());
  }).catch(error=>{
    if(request===coreRequestRef.current)failures.push('Calendário: '+(error?.message||'indisponível'));
  });
  await Promise.all([teamsTask,gamesTask]);
  if(request===coreRequestRef.current){
    if(failures.length)setError(failures.join(' · '));
    setBusy(false);
  }
},[api,from,to]);
 useEffect(()=>{if(session){loadSettings();loadFavorites();loadCore();}else{favoritesRequestRef.current++;setFavorites([]);}},[session,loadSettings,loadFavorites,loadCore]);
 useEffect(()=>{
  if(!session||!['overview','games','livecenter','customcalendar','boxscore'].includes(page))return;
  let running=false;
  let active=true;
  const refreshLive=async()=>{
    if(!active||running||document.visibilityState!=='visible')return;
    running=true;
    try {
      const gamesResult=await api('/api/games/live',{cache:false});
      if(!active)return;
      const updates=gamesResult.data||[];
      setLiveUnavailable(false);
      const sameGame=(left,right)=>{if(!left||!right)return false;const leftId=left.id==null?'':String(left.id),rightId=right.id==null?'':String(right.id);if(leftId&&rightId&&leftId===rightId)return true;const date=String(left.date||''),home=String(left.home_team?.abbreviation||''),away=String(left.visitor_team?.abbreviation||'');return Boolean(date&&home&&away&&date===String(right.date||'')&&home===String(right.home_team?.abbreviation||'')&&away===String(right.visitor_team?.abbreviation||''));};
      if(updates.length)setGames(current=>{
        const byId=new Map(current.map(game=>[String(game.id),game]));
        updates.forEach(game=>{
          const match=[...byId.entries()].find(([,existing])=>sameGame(existing,game));
          if(match){byId.delete(match[0]);const previous=match[1];byId.set(String(game.id),{...previous,...game});}
          else byId.set(String(game.id),game);
        });
        return [...byId.values()].sort((x,y)=>new Date(x.datetime||x.date)-new Date(y.datetime||y.date));
      });
      setLastSync(new Date());
      const selectedGame=boxGameRef.current;
      const updated=updates.find(game=>sameGame(game,selectedGame));
      if(updated)setBoxGame(current=>current&&sameGame(current,updated)?({...current,...updated}):current);
      const activeGame=updated||selectedGame;
      if(page==='boxscore'&&activeGame?.id&&(activeGame.status_state==='in_progress'||activeGame.status_state==='final')){
        const boxRequest=boxRequestRef.current;
        const score=await api('/api/games/'+encodeURIComponent(activeGame.id)+'/stats',{cache:false});
        if(!active||boxRequest!==boxRequestRef.current||!sameGame(boxGameRef.current,activeGame))return;
        setBoxStats(score.data||[]);
      }
    } catch(e) { if(active)setLiveUnavailable(true); /* Mantém os últimos dados válidos durante falhas transitórias. */ }
    finally { running=false; }
  };
  const onVisible=()=>{if(document.visibilityState==='visible')refreshLive();};
  document.addEventListener('visibilitychange',onVisible);
  refreshLive();
  const timer=window.setInterval(refreshLive,15000);
  return()=>{active=false;window.clearInterval(timer);document.removeEventListener('visibilitychange',onVisible);};
},[session,api,page,liveRefreshTick]);
