 const toggleFavorite=async(p)=>{
  if(!supabase||!session?.user)return;
  const userId=session.user.id,sessionEpoch=favoriteSessionEpochRef.current,id=Number(p.id||p.player?.id);
  if(!Number.isSafeInteger(id)||id<=0){setError('Não foi possível identificar o ID deste jogador para salvar o favorito.');return;}
  const mutationKey=userId+':'+id,mutationToken=Symbol('favorite');
  if(favoriteMutationRef.current.has(mutationKey))return;
  favoriteMutationRef.current.set(mutationKey,mutationToken);
  favoritesRequestRef.current+=1; // Invalida apenas uma leitura de favoritos iniciada antes desta mutação.
  const name=p.name||[p.first_name||p.player?.first_name||'',p.last_name||p.player?.last_name||''].filter(Boolean).join(' ');
  const existing=favorites.filter(f=>String(f.player_id)===String(id)||normalizePlayerKey(f.player_name)===normalizePlayerKey(name));
  try{
    if(existing.length){
      const ids=existing.map(f=>f.player_id);
      const {error:e}=await supabase.from('favorites').delete().eq('user_id',userId).in('player_id',ids);
      if(sessionEpoch!==favoriteSessionEpochRef.current||session?.user?.id!==userId)return;
      if(e)setError(e.message);
      else setFavorites(current=>current.filter(f=>!ids.some(existingId=>String(existingId)===String(f.player_id))));
    }else{
      const {data,error:e}=await supabase.from('favorites').insert({user_id:userId,player_id:id,player_name:name,team_abbreviation:p.team?.abbreviation||p.team_abbreviation||null}).select().single();
      if(sessionEpoch!==favoriteSessionEpochRef.current||session?.user?.id!==userId)return;
      if(e)setError(e.message);
      else setFavorites(current=>current.some(f=>String(f.player_id)===String(id))?current:[data,...current]);
    }
  }catch(error){
    if(sessionEpoch===favoriteSessionEpochRef.current&&session?.user?.id===userId)setError('Não foi possível atualizar este favorito: '+(error?.message||'falha de conexão com o Supabase.'));
  }finally{
    if(favoriteMutationRef.current.get(mutationKey)===mutationToken)favoriteMutationRef.current.delete(mutationKey);
  }
};
