    {page==='homeaway'&&<><p className="muted">Campanha em casa e fora calculada pelos jogos finalizados no calendário carregado.</p><div className="table-wrap"><table><thead><tr><th>Time (A–Z)</th><th>Casa V–D</th><th>Fora V–D</th><th>Total</th></tr></thead><tbody>{teamRowsAlpha.map(x=><tr key={x.team.id}><td>{x.team.full_name}</td><td>{x.homeRecord||'Sem dados na amostra'}</td><td>{x.awayRecord||'Sem dados na amostra'}</td><td>{x.totalRecord||'Sem partidas finalizadas'}</td></tr>)}</tbody></table></div><p className="muted">Amostra limitada ao intervalo atualmente carregado.</p></>}
