    {page==='streaks'&&<div className="table-wrap"><table><thead><tr><th>Time (A–Z)</th><th>Sequência atual</th><th>Últimos resultados</th></tr></thead><tbody>{teamRowsAlpha.map(x=><tr key={x.team.id}><td>{x.team.full_name}</td><td>{x.streak?x.streak+' '+(x.streakKind==='V'?'vitória(s)':'derrota(s)'):'Sem partidas no período'}</td><td>{x.form.join(' · ')||'Sem resultados no período'}</td></tr>)}</tbody></table></div>}
    {page==='rest'&&<><p className="muted">Intervalo entre último e próximo jogo no calendário carregado. Não inclui viagens nem confirmação de descanso de titulares.</p><div className="table-wrap"><table><thead><tr><th>Time (A–Z)</th><th>Último jogo</th><th>Próximo jogo</th><th>Dias</th></tr></thead><tbody>{teamRowsAlpha.map(x=><tr key={x.team.id}><td>{x.team.full_name}</td><td>{x.lastDate||'Sem jogo no período'}</td><td>{x.nextDate||'Sem jogo futuro no período'}</td><td>{x.restDays==null?'Sem dados suficientes':x.restDays}</td></tr>)}</tbody></table></div></>}
    {page==='schedulestrength'&&<><p className="muted">Quantidade de jogos futuros no calendário carregado e aproveitamento médio dos adversários conhecidos.</p><div className="table-wrap"><table><thead><tr><th>Time (A–Z)</th><th>Jogos futuros</th><th>Win% médio adversários</th></tr></thead><tbody>{teamRowsAlpha.map(x=>{const opp=x.upcoming.map(g=>g.home_team?.abbreviation===x.team.abbreviation?g.visitor_team?.abbreviation:g.home_team?.abbreviation),rates=opp.map(ab=>teamStats.find(t=>t.team?.abbreviation===ab)?.win_pct).filter(v=>v!=null),avg=rates.length?rates.reduce((s,v)=>s+Number(v),0)/rates.length:null;return <tr key={x.team.id}><td>{x.team.full_name}</td><td>{x.upcoming.length}</td><td>{avg==null?'Sem dados dos adversários':pct(avg)}</td></tr>})}</tbody></table></div><p className="muted">É um indicador simples da amostra, não um modelo oficial de dificuldade.</p></>}
