 {page==='betlab'&&(()=>{const gameOptions=sortedGames.filter(g=>['scheduled','in_progress'].includes(g.status_state));const game=gameOptions.find(g=>String(g.id)===String(betGameId))||gameOptions[0];const odds=Number(betOdds),prob=Number(betProbability)/100,stake=Number(betStake);const valid=Number.isFinite(odds)&&odds>1&&Number.isFinite(prob)&&prob>0&&prob<1&&Number.isFinite(stake)&&stake>0;const implied=valid?1/odds:null;const expected=valid?stake*(prob*odds-1):null;const fair=valid?1/prob:null;const kellyFraction=valid?Math.max(0,Math.min(1,(prob*odds-1)/(odds-1)))*.5:null;const home=teamStats.find(x=>x.team?.abbreviation===game?.home_team?.abbreviation);const away=teamStats.find(x=>x.team?.abbreviation===game?.visitor_team?.abbreviation);const awayPlayers=averages.filter(p=>p.team?.abbreviation===game?.visitor_team?.abbreviation&&p.pts!=null&&Number.isFinite(Number(p.pts))).slice().sort((a,b)=>Number(b.pts)-Number(a.pts)).slice(0,3);const homePlayers=averages.filter(p=>p.team?.abbreviation===game?.home_team?.abbreviation&&p.pts!=null&&Number.isFinite(Number(p.pts))).slice().sort((a,b)=>Number(b.pts)-Number(a.pts)).slice(0,3);return <><div className="mvp-card"><TrendingUp size={28}/><div><h2>Courtside Betting Lab</h2><p>Compare dados reais, preço de mercado e sua própria estimativa de probabilidade. Nenhum cálculo garante lucro.</p></div></div><div className="filters"><label>Partida<select value={game?.id||''} onChange={e=>setBetGameId(e.target.value)}><option value="">Selecione uma partida</option>{gameOptions.map(g=><option key={g.id} value={g.id}>{g.visitor_team?.abbreviation} @ {g.home_team?.abbreviation} · {g.date}</option>)}</select></label><label>Odd decimal<input type="number" min="1.01" step="0.01" placeholder="Ex.: 1.90" value={betOdds} onChange={e=>setBetOdds(e.target.value)}/></label><label>Sua probabilidade estimada (%)<input type="number" min="0.1" max="99.9" step="0.1" placeholder="Ex.: 55" value={betProbability} onChange={e=>setBetProbability(e.target.value)}/></label><label>Stake (R$)<input type="number" min="1" step="1" value={betStake} onChange={e=>setBetStake(e.target.value)}/></label></div>{valid?<><div className="cards"><div className="metric-card"><span>Probabilidade implícita da odd</span><b>{fmt(implied*100,2)}%</b></div><div className="metric-card"><span>Seu edge estimado</span><b>{fmt((prob-implied)*100,2)} p.p.</b></div><div className="metric-card"><span>Valor esperado por aposta</span><b>{expected>=0?'+':''}R$ {fmt(expected,2)}</b></div><div className="metric-card"><span>Odd justa pela sua estimativa</span><b>{fmt(fair,2)}</b></div></div><div className="metric-guide"><b>Gestão de risco · ½ Kelly teórico</b><p>Fração teórica de ½ Kelly: <strong>{fmt(kellyFraction*100,1)}% da banca</strong>. Esse valor depende totalmente da probabilidade que você informou; se ela estiver errada, o cálculo também estará.</p><p>{expected>0?'Sua estimativa aponta valor esperado positivo antes de considerar limites, margem da casa e variância.':'Com a probabilidade informada, a odd não oferece valor esperado positivo.'}</p></div></>:<p className="notice">Informe odd maior que 1, probabilidade entre 0% e 100% e stake positiva.</p>}<h3>Contexto estatístico da partida</h3>{game?<div className="bet-match-grid">{[{label:game.visitor_team?.full_name||'Visitante',team:away},{label:game.home_team?.full_name||'Mandante',team:home}].map(x=><div className="metric-guide" key={x.label}><b>{x.label}</b><p>Campanha: {x.team?.wins??'Não disponível'}–{x.team?.losses??'Não disponível'} · Win% {x.team?.win_pct==null?'Não disponível':pct(x.team.win_pct)}</p><p>Net Rating: {fmt(x.team?.net_rating,1)||'Não disponível'} · PTS {fmt(x.team?.pts)||'Não disponível'} · REB {fmt(x.team?.reb)||'Não disponível'} · AST {fmt(x.team?.ast)||'Não disponível'}</p></div>)}</div>:<p className="muted">Nenhuma partida futura ou ao vivo no calendário carregado.</p>}{game&&<div className="bet-player-grid">{[{label:game.visitor_team?.full_name||'Visitante',players:awayPlayers},{label:game.home_team?.full_name||'Mandante',players:homePlayers}].map(side=><div className="metric-guide" key={side.label}><b>Principais pontuadores · {side.label}</b>{side.players.length?side.players.map(p=><p key={p.player.id}>{p.player.first_name} {p.player.last_name} · {fmt(p.pts)} PTS · {fmt(p.reb)} REB · {fmt(p.ast)} AST</p>):<p>Estatísticas individuais indisponíveis.</p>}</div>)}</div>}<p className="muted">As odds e a probabilidade são preenchidas por você. O Courtside não recebe odds de casas de apostas nem fornece picks garantidos. Compare escalações, lesões, descanso, mercado e regras da casa antes de decidir.</p></>})()}
