 {page==='boxscore'&&<section className="panel"><div className="panel-head"><button className="secondary" onClick={()=>setPage('games')}><ChevronLeft size={16}/> {t.games}</button><h2>{boxGame?.visitor_team?.full_name} @ {boxGame?.home_team?.full_name}</h2></div><p className="muted">{boxGame?.date} · {boxGame?.status}{boxGame?.period_label?' · '+boxGame.period_label:''}{boxGame?.status_state==='in_progress'?' · '+(boxGame?.display_clock?formatGameClock(boxGame.display_clock):'Relógio oficial indisponível'):''} · {boxGame?.visitor_team_score??'Não disponível'} – {boxGame?.home_team_score??'Não disponível'}</p>{boxStats.length? <><div className="game-standouts">{[{label:'Maior pontuador',key:'pts',unit:'PTS'},{label:'Mais rebotes',key:'reb',unit:'REB'},{label:'Mais assistências',key:'ast',unit:'AST'},{label:'Melhor Game Score',key:'game_score',unit:'GmSc'}].map(item=>{const leader=boxStats.filter(p=>p[item.key]!=null).slice().sort((a,b)=>Number(b[item.key])-Number(a[item.key]))[0];return <div className="metric-card" key={item.key}><span>{item.label}</span>{leader?<><b>{leader.player?.first_name} {leader.player?.last_name}</b><strong>{fmt(leader[item.key],item.key==='game_score'?2:0)} {item.unit}</strong></>:<b>Não disponível</b>}</div>})}</div><div className="table-wrap"><table><thead><tr><th>#</th><th>{t.player}</th><th>{t.team}</th><th>MIN</th><th>PTS</th><th>REB</th><th>AST</th><th>STL</th><th>BLK</th><th>FG%</th><th>3P%</th><th>TOV</th><th>Nota CF*</th><th>Game Score</th><th>Marcos</th></tr></thead><tbody>{boxStats.map((s,i)=>{const scores=boxStats.filter(x=>x.game_score!=null&&Number.isFinite(Number(x.game_score))).map(x=>Number(x.game_score));const minScore=scores.length?Math.min(...scores):null;const maxScore=scores.length?Math.max(...scores):null;const grade=s.game_score==null?null:maxScore>minScore?Math.round((s.game_score-minScore)/(maxScore-minScore)*100):50;const doubleStats=[s.pts,s.reb,s.ast,s.stl,s.blk].filter(v=>Number(v)>=10).length;const milestones=[Number(s.pts)>=30?'30+ PTS':Number(s.pts)>=20?'20+ PTS':null,Number(s.reb)>=10?'10+ REB':null,Number(s.ast)>=10?'10+ AST':null,doubleStats>=3?'TRIPLE-DOUBLE':doubleStats>=2?'DOUBLE-DOUBLE':null].filter(Boolean);return <tr key={s.id}><td>{i+1}</td><td><div className="player-cell">{(s.player?.headshot||s.player?.id)&&<img className="player-headshot" src={s.player?.headshot||("https://cdn.nba.com/headshots/nba/latest/260x190/"+s.player.id+".png")} alt="" loading="lazy" onError={e=>{e.currentTarget.style.visibility="hidden";}}/>}<b>{s.player?.first_name} {s.player?.last_name}</b></div></td><td>{s.team?.abbreviation}</td><td>{formatMinutes(s.min)||'Não disponível'}</td><td>{s.pts??'Não disponível'}</td><td>{s.reb??'Não disponível'}</td><td>{s.ast??'Não disponível'}</td><td>{s.stl??'Não disponível'}</td><td>{s.blk??'Não disponível'}</td><td>{s.fg_pct==null?'Não disponível':fmt(s.fg_pct*100)+'%'}</td><td>{s.fg3_pct==null?'Não disponível':fmt(s.fg3_pct*100)+'%'}</td><td>{s.turnover??'Não disponível'}</td><td><b className="grade-pill">{grade==null?'Não disponível':grade+'/100'}</b></td><td>{s.game_score==null?'Não disponível':fmt(s.game_score,2)}</td><td>{milestones.length?<div className="milestone-tags">{milestones.map(mark=><span key={mark}>{mark}</span>)}</div>:<span className="muted">Não disponível</span>}</td></tr>})}</tbody></table></div><p className="muted">Game Score usa a fórmula estatística de John Hollinger para resumir a contribuição individual na partida. Nota CF* é uma escala relativa de 0 a 100 comparada aos atletas que jogaram esta partida; não é nota oficial da NBA. Atletas sem minutos jogados são excluídos, evitando linhas de DNP com zeros falsos.</p></>:<div className="empty-state"><p className="muted">{busy?'Carregando estatísticas da partida…':error||(boxGame?.status_state==='scheduled'?'A partida ainda não começou. As estatísticas individuais aparecem após a publicação do box score.':boxGame?.status_state==='in_progress'?'A fonte ainda não publicou as estatísticas individuais desta partida. Tente atualizar em instantes.':'A fonte não retornou estatísticas individuais para esta partida.')}</p><button className="secondary" disabled={busy||!boxGame?.id} onClick={()=>boxGame&&openBox(boxGame)}>Atualizar box score</button></div>}</section>}
