function DataTable({rows,render,t}){return rows?.length?<div className="table-wrap"><table><thead><tr><th>#</th><th>{t.player}</th><th>{t.team}</th><th>GP</th><th>{t.pts}</th><th>{t.reb}</th><th>{t.ast}</th><th>{t.stl}</th><th>{t.blk}</th><th>FG%</th><th>3P%</th><th>★</th></tr></thead><tbody>{rows.map((p,i)=>render(p,i))}</tbody></table></div>:<p className="muted">{t.noData}</p>}
function gameLocalDate(game){
 const value=game.datetime||game.date;
 if(!value)return '';
 if(!game.datetime&&/^\d{4}-\d{2}-\d{2}$/.test(String(game.date)))return String(game.date);
 const date=new Date(value);
 if(!Number.isFinite(date.getTime()))return String(game.date||'').slice(0,10);
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);
 const get=type=>parts.find(part=>part.type===type)?.value||'';
 return get('year')+'-'+get('month')+'-'+get('day');
}
function formatGameDateTime(game,lang='pt'){
 const value=game.datetime||game.date;
 const missingTime=lang==='en'?'Time not announced':lang==='es'?'Horario no anunciado':'Horário não informado';
 if(!value)return missingTime;
 const hasTime=typeof value==='string'&&value.includes('T');
 const date=new Date(hasTime?value:String(value)+'T12:00:00Z');
 if(!Number.isFinite(date.getTime()))return game.date||'Horário não informado';
 const locale=lang==='en'?'en-US':lang==='es'?'es-ES':'pt-BR';
 const dateText=new Intl.DateTimeFormat(locale,{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'}).format(date);
 if(!hasTime)return dateText+' · '+missingTime;
 const timeText=new Intl.DateTimeFormat(locale,{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hour12:false}).format(date);
 return dateText+' · '+timeText+' (Brasília)';
}
function formatGameClock(value){
 const raw=String(value??'').trim();
 const match=raw.match(/^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?$/i);
 if(!match)return raw;
 const seconds=Math.round(Number(match[1]||0)*3600+Number(match[2]||0)*60+Number(match[3]||0));
 return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');
}
function GameList({games,onOpen,t,lang='pt'}){
 const labels={pt:{live:'● AO VIVO',scheduled:'Agendado',postponed:'Adiado',cancelled:'Cancelado',suspended:'Suspenso',delayed:'Atrasado',away:'Visitante',home:'Mandante',awaiting:'Aguardando jogo',time:'Horário não informado',vs:'VS',scorePending:'Placar em atualização',noScore:'Placar indisponível',clockUnavailable:'Relógio oficial indisponível'},en:{live:'● LIVE',scheduled:'Scheduled',postponed:'Postponed',cancelled:'Canceled',suspended:'Suspended',delayed:'Delayed',away:'Away',home:'Home',awaiting:'Awaiting game',time:'Time not announced',vs:'VS',scorePending:'Score updating',noScore:'Score unavailable',clockUnavailable:'Official clock unavailable'},es:{live:'● EN VIVO',scheduled:'Programado',postponed:'Aplazado',cancelled:'Cancelado',suspended:'Suspendido',delayed:'Retrasado',away:'Visitante',home:'Local',awaiting:'Esperando el partido',time:'Horario no anunciado',vs:'VS',scorePending:'Actualizando marcador',noScore:'Marcador no disponible',clockUnavailable:'Reloj oficial no disponible'}};
 const copy=labels[lang]||labels.pt;
 return games?.length?<div className="games-list">{games.map(g=>{
  const live=g.status_state==='in_progress',final=g.status_state==='final',hasScore=[g.visitor_team_score,g.home_team_score].every(value=>value!==null&&value!==undefined&&String(value).trim()!==''&&Number.isFinite(Number(value))),canOpen=live||final;
  const rawStatus=String(g.status||'').toLowerCase();
  const status=live?copy.live:final?'FINAL':rawStatus.includes('postpon')?copy.postponed:rawStatus.includes('cancel')?copy.cancelled:rawStatus.includes('suspend')?copy.suspended:rawStatus.includes('delay')?copy.delayed:copy.scheduled;
  const clock=live?' · '+(g.period_label?g.period_label+' ':'')+(g.display_clock?formatGameClock(g.display_clock):copy.clockUnavailable):'';
  const visitorAbbr=g.visitor_team?.abbreviation||g.visitor_team?.full_name||copy.away;
  const homeAbbr=g.home_team?.abbreviation||g.home_team?.full_name||copy.home;
  const visitorLogo=TEAM_LOGO_IDS[g.visitor_team?.abbreviation],homeLogo=TEAM_LOGO_IDS[g.home_team?.abbreviation];
  const logo=(teamId)=>teamId?'https://cdn.nba.com/logos/nba/'+teamId+'/global/L/logo.svg':null;
  const score=hasScore?g.visitor_team_score+' : '+g.home_team_score:live?copy.scorePending:final?copy.noScore:copy.vs;
  return <article className={'game-row '+(live?'game-live':'')} key={g.id}>
   <div className="game-matchup"><b className="game-matchup-teams"><span className="game-team">{visitorLogo&&<img className="game-team-logo" src={logo(visitorLogo)} alt="" aria-hidden="true" loading="lazy" decoding="async" onError={e=>{e.currentTarget.style.display='none';}}/>}<strong>{visitorAbbr}</strong></span><span className="game-at">@</span><span className="game-team">{homeLogo&&<img className="game-team-logo" src={logo(homeLogo)} alt="" aria-hidden="true" loading="lazy" decoding="async" onError={e=>{e.currentTarget.style.display='none';}}/>}<strong>{homeAbbr}</strong></span></b><small>{g.visitor_team?.full_name||copy.away} vs {g.home_team?.full_name||copy.home}</small></div>
   <div className="game-score"><b>{score}</b><small className={live?'status-live':final?'status-final':'status-scheduled'}>{status}{clock}</small></div>
   <div className="game-meta"><small>{formatGameDateTime(g,lang)||copy.time}</small><button className="text-btn" disabled={!canOpen} title={canOpen?t.details:copy.awaiting} onClick={()=>onOpen(g)}>{canOpen?t.details:copy.awaiting} →</button></div>
  </article>;
 })}</div>:<p className="muted">{t.noData}</p>;
}
